input.command:
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
# Cirrus function URL rejects query keys outside A-Za-z0-9_.- (400 InvalidQueryStringKey)
for f in event seat refund; do
  bash bin/render "$f" | grep -o 'action="[^"]*"' | while read -r l; do
    u=${l#action=\"}; u=${u%\"}; k=${u#\?}; k=${k%%=*}
    [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "invalid query key: $k"; exit 1; }
  done || fail=1
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/events/88/seats?action=assign' | grep -q '^200 assign' || { echo "handle assign"; fail=1; }
bash bin/handle POST '/orders/5012/refund?action=refund' | grep -q '^200 refund' || { echo "handle refund"; fail=1; }
exit $fail
EOF
bash tests/forms_test.sh; echo before=$?
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The key must stay within A-Za-z0-9_.- : Cirrus function URLs reject other keys with 400 InvalidQueryStringKey.
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
EOF
bash tests/forms_test.sh; echo after=$?; bash scripts/verify.sh | tail -5; grep -rn '?/' --include=* . 2>/dev/null | grep -v '^./ops\|^./.git/' | head
